import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { partyId, venueId, userId, customName, customAddress, customNotes, isCustom } = body;

    // Validate required parameters
    if (!partyId || !userId) {
      return NextResponse.json(
        { error: 'Party ID and User ID are required' },
        { status: 400 }
      );
    }

    if (!isCustom && !venueId) {
      return NextResponse.json(
        { error: 'Venue ID is required for selected venues' },
        { status: 400 }
      );
    }

    if (isCustom && !customName) {
      return NextResponse.json(
        { error: 'Custom name is required for custom venues' },
        { status: 400 }
      );
    }

    // Prepare venue data
    const venueData = {
      party_id: partyId,
      venue_id: isCustom ? null : venueId,
      user_id: userId,
      custom_name: isCustom ? customName : null,
      custom_address: isCustom ? customAddress : null,
      custom_notes: isCustom ? customNotes : null,
      is_custom: isCustom || false,
    };

    console.log('API: Saving party venue:', venueData);

    // Upsert party venue (replace existing selection)
    const { data: partyVenue, error } = await supabase
      .from('party_venues')
      .upsert(venueData, { 
        onConflict: 'party_id',
        ignoreDuplicates: false 
      })
      .select(`
        *,
        venues (
          id,
          name,
          address,
          phone,
          website,
          rating,
          reviews_count,
          photos
        )
      `)
      .single();

    if (error) {
      console.error('Database error saving party venue:', error);
      return NextResponse.json(
        { error: 'Failed to save venue selection', details: error.message },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      partyVenue
    });

  } catch (error) {
    console.error('API Error saving party venue:', error);

    return NextResponse.json(
      { 
        error: 'Failed to save venue selection',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const partyId = searchParams.get('partyId');

    if (!partyId) {
      return NextResponse.json(
        { error: 'Party ID is required' },
        { status: 400 }
      );
    }

    // Get party venue selection
    const { data: partyVenue, error } = await supabase
      .from('party_venues')
      .select(`
        *,
        venues (
          id,
          place_id,
          name,
          address,
          formatted_address,
          phone,
          website,
          rating,
          reviews_count,
          photos,
          opening_hours,
          latitude,
          longitude
        )
      `)
      .eq('party_id', partyId)
      .single();

    if (error && error.code !== 'PGRST116') { // PGRST116 = no rows returned
      console.error('Database error getting party venue:', error);
      return NextResponse.json(
        { error: 'Failed to get venue selection', details: error.message },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      partyVenue: partyVenue || null
    });

  } catch (error) {
    console.error('API Error getting party venue:', error);

    return NextResponse.json(
      { 
        error: 'Failed to get venue selection',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}

export async function DELETE(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const partyId = searchParams.get('partyId');

    if (!partyId) {
      return NextResponse.json(
        { error: 'Party ID is required' },
        { status: 400 }
      );
    }

    // Delete party venue selection
    const { error } = await supabase
      .from('party_venues')
      .delete()
      .eq('party_id', partyId);

    if (error) {
      console.error('Database error deleting party venue:', error);
      return NextResponse.json(
        { error: 'Failed to delete venue selection', details: error.message },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true
    });

  } catch (error) {
    console.error('API Error deleting party venue:', error);

    return NextResponse.json(
      { 
        error: 'Failed to delete venue selection',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
}
